def process_text(inline: 'InlineParser', text: str, state: 'InlineState'
    ) ->None:
    ref_abbrs = state.env.get('ref_abbrs', {})
    if not ref_abbrs:
        # No abbreviations defined, just append the text as-is
        state.append_token({'type': 'text', 'raw': text})
        return

    # Sort by length (longest first) to match longer abbreviations first
    sorted_abbrs = sorted(ref_abbrs.keys(), key=len, reverse=True)

    pos = 0
    while pos < len(text):
        matched = False

        # Try to match each abbreviation at current position
        for abbr in sorted_abbrs:
            if text[pos:pos+len(abbr)] == abbr:
                # Check word boundaries
                # Character before must not be alphanumeric
                if pos > 0 and text[pos-1].isalnum():
                    continue
                # Character after must not be alphanumeric
                if pos + len(abbr) < len(text) and text[pos+len(abbr)].isalnum():
                    continue

                # Found a match - append any text before it
                if pos > 0:
                    # Find the start of current text segment
                    start = pos
                    while start > 0 and text[start-1].isalnum():
                        start -= 1
                    if start < pos:
                        state.append_token({'type': 'text', 'raw': text[start:pos]})

                # Append the abbreviation token
                state.append_token({
                    'type': 'abbr',
                    'raw': abbr,
                    'attrs': {'title': ref_abbrs[abbr]}
                })
                pos += len(abbr)
                matched = True
                break

        if not matched:
            # No abbreviation matched, collect text until next potential match
            start = pos
            pos += 1
